"""Deterministic, local-only Chemistry chapter 1 practice drafts; no DB or network.
350 MCQ + 50 CQ + 70 SQ. Research/safety scenario variants are explicitly tagged.
Textbook chapter pp1–16 was visually inspected, not OCR-claimed or teacher-certified.
"""
from pathlib import Path
from collections import Counter
import hashlib, html, json, re, sys
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'content/question-bank/ssc/chemistry/chapter-1'
DOC=ROOT/'docs/question-bank/ssc-chemistry'
ASSET=ROOT/'public/question-bank/ssc-chemistry-ch1-v1'
SOURCE='https://drive.google.com/file/d/17cFTHipiCnU5qB-prqtRRj6YADFdZ091/view'
TOPIC='১ম অধ্যায়: রসায়নের ধারণা'
items=[]; review=[]
def add(kind,text,explanation,family,page,**kw):
    items.append(dict(type=kind,text=text,explanation=explanation,page=f'মূল ধারণা: পাঠ্যবই পৃ. {page}; নিজস্ব অনুশীলনী, বোর্ড প্রশ্ন নয়',difficulty=kw.pop('difficulty','MEDIUM'),**kw))
    review.append(dict(index=len(items),kind=kind,family=family,textbookPages=page,originalPractice=True,teacherApproved=False))
def mcq(q,a,wrong,why,family,page):
    assert len(wrong)==3 and len(set([a,*wrong]))==4,(q,a,wrong)
    n=sum(x['type']=='MCQ' for x in items); pos=n%4
    opts=list(wrong);opts.insert(pos,a)
    add('MCQ',q,why,family,page,options=dict(zip('ABCD',opts)),correct='ABCD'[pos])
def sq(q,a,family,page):add('SQ',q,a,family,page)
def cq(stem,parts,family,page):
    assert len(parts)==4
    add('CQ',stem,'উপপ্রশ্নভিত্তিক নমুনা উত্তর দেওয়া আছে; শিক্ষক যাচাই বাকি।',family,page,difficulty='HARD',parts=[dict(label=label,question=q,solution=a,marks=i) for i,(label,(q,a)) in enumerate(zip('কখগঘ',parts),1)])
def image(name,alt):return f'![{alt}](https://proshnobook.com/question-bank/ssc-chemistry-ch1-v1/{name}.png)'
