blocks=[]
def markup(t):
    t=html.escape(t)
    t=re.sub(r'!\[([^\]]*)\]\(https://proshnobook\.com(/question-bank/[^)]+)\)',lambda m:f'<img alt="{m[1]}" src="../../../public{m[2]}">',t)
    lines=t.split('\n');out=[];i=0
    while i<len(lines):
        if lines[i].startswith('|') and i+1<len(lines) and lines[i+1].startswith('|---'):
            cells=lambda s:[c.strip() for c in s.strip('|').split('|')]
            headers=cells(lines[i]);i+=2;rows=[]
            while i<len(lines) and lines[i].startswith('|'):rows.append(cells(lines[i]));i+=1
            out.append('<table><thead><tr>'+''.join('<th>'+c+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>')
        else:out.append(lines[i]);i+=1
    return '<br>'.join(out)
for kind,title in [('MCQ','MCQ — 350'),('CQ','CQ — 50'),('SQ','SQ — 70')]:
    blocks.append(f'<h2 id="{kind}">{title}</h2>')
    for n,q in enumerate([x for x in items if x['type']==kind],1):
        body=f'<h3>{n}. {markup(q["text"])}</h3>'
        if kind=='MCQ':body+=''.join(f'<p>{k}. {html.escape(v)}</p>' for k,v in q['options'].items())+f'<p class="answer">উত্তর: {q["correct"]} — {html.escape(q["explanation"])}</p>'
        elif kind=='CQ':body+=''.join(f'<p><b>{x["label"]}) ({x["marks"]}) {html.escape(x["question"])}</b></p><p class="answer">{html.escape(x["solution"])}</p>' for x in q['parts'])
        else:body+=f'<p class="answer">{html.escape(q["explanation"])}</p>'
        blocks.append('<article>'+body+f'<small>{html.escape(q["page"])}</small></article>')
